import random, time

def drain_iceberg_backlog(spark, table: str, partition_dates: list[str], max_retries: int = 3) -> None:
    for dt in partition_dates:
        sql = f'''
            CALL iceberg.system.rewrite_data_files(
                table => '{table}',
                where => "event_date = DATE '{dt}'",
                options => map(
                    'target-file-size-bytes', '536870912',
                    'min-input-files', '5',
                    'partial-progress.enabled', 'true',
                    'partial-progress.max-commits', '10',
                    'max-concurrent-file-group-rewrites', '4'
                )
            )
        '''
        for attempt in range(max_retries):
            try:
                spark.sql(sql)
                break
            except Exception as exc:
                if attempt == max_retries - 1:
                    raise RuntimeError(f'Backlog drain stalled on {dt}: {exc}') from exc
                time.sleep((5.0 * (2 ** attempt)) + random.uniform(0, 2.0))
